import heapq
import sys

def main():
    import sys
    import heapq

    def read_ints():
        return map(int, sys.stdin.readline().split())

    n, m, k = read_ints()

    # List of flights sorted by departure day
    flights = []
    for _ in range(m):
        d, f, t, c = read_ints()
        flights.append((d, f, t, c))

    flights.sort()

    # Priority queues for each city to store the cheapest flights
    pq = [[] for _ in range(n + 1)]
    for d, f, t, c in flights:
        if f == 0:
            heapq.heappush(pq[t], (c, d))
        else:
            heapq.heappush(pq[f], (c, d))

    # Array to store the minimum cost to reach Metropolis for each city
    min_cost = [float('inf')] * (n + 1)
    min_cost[0] = 0

    # Array to store the last day each city was in Metropolis
    last_day_in_metropolis = [-1] * (n + 1)

    current_day = 0
    for d, f, t, c in flights:
        current_day = max(current_day, d)

        # Update the cost for the city where the flight departs
        if f != 0:
            if len(pq[f]) > 0:
                cost, day = heapq.heappop(pq[f])
                if day <= current_day:
                    min_cost[f] = min(min_cost[f], cost)

        # Update the cost for the city where the flight arrives
        if t != 0:
            if len(pq[t]) > 0:
                cost, day = heapq.heappop(pq[t])
                if day <= current_day:
                    min_cost[t] = min(min_cost[t], cost)

        # Check if all jury members are in Metropolis for k days
        if current_day >= k:
            all_in_metropolis = True
            for i in range(1, n + 1):
                if last_day_in_metropolis[i] < current_day - k:
                    all_in_metropolis = False
                    break

            if all_in_metropolis:
                total_cost = sum(min_cost)
                print(total_cost)
                return

    # If we exit the loop without finding a valid arrangement
    print(-1)

if __name__ == "__main__":
    main()
